    if (x0 < 60) ctx.fillRect(x0, y0, Math.min(60, x1) - x0, y1 - y0);
    ctx.fillStyle = PALETTE.sand;
    if (x1 > 60) ctx.fillRect(Math.max(60, x0), y0, Math.min(190, x1) - Math.max(60, x0), y1 - y0);
